module Top;
    int by_key[int];
    int r[$];
    initial begin
        by_key[10] = 1; by_key[-5] = 2; by_key[3] = 2;
        foreach (by_key[k]) $display("key %0d", k);
        r = by_key.find_index with (item == 2);
        $display("find_index size=%0d first=%0d", r.size(), r[0]);
        r = by_key.max with (item.index);
        $display("max by index size=%0d value=%0d", r.size(), r[0]);
    end
endmodule
